    adj = defaultdict(list)
    for a, b in edges:
        adj[a].append(b)

    # Special case: source equals target -> need a cycle of length > 0
    if src == dst:
        q = deque()
        q.append((src, 0))          # (node, distance from src)
        visited = {src}
        while q:
            node, dist = q.popleft()
            for nb in adj[node]:
                if nb == dst:       # found a return path
                    return dist + 1
                if nb not in visited:
                    visited.add(nb)
                    q.append((nb, dist + 1))
        return None                 # no cycle reachable

    # General case: source != target
    q = deque()
    q.append((src, 0))
    visited = {src}
    while q:
